            new Uri("http://origin.example.com/start"),
            new Dictionary<string, string>(),
            null,
            noRedirect: false
        );

        Assert.Equal(200, response.StatusCode);
        Assert.Equal(2, handler.Requests.Count);
    }

    // ---- 3.3: HTTPS->HTTP body replay guard ----

    [Fact]
    public async Task RefusesBodyReplayOnHttpsToHttpDowngrade()
    {
        var handler = new RedirectingHandler(
            firstStatus: HttpStatusCode.RedirectKeepVerb,
            location: new Uri("http://downgraded.example.com/landed"));
        var client = new DefaultApiClient(new HttpClient(handler));
        // POST with a body over HTTPS, redirected (307) to plain HTTP.
        // T-D2: the downgraded body-replay is refused as a typed SDK error
        // (not a silent return of the 307) so the caller can observe it.
        var ex = await Assert.ThrowsAsync<ApiException>(() => client.SendRequestAsync(
            "POST",
            new Uri("https://secure.example.com/start"),
            new Dictionary<string, string>(),
            "secret-payload"
        ));

        // Only the original encrypted request must have been made; the
        // downgraded follow-up must be refused.
        Assert.Single(handler.Requests);
        Assert.Contains("downgrade", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    // ---- T-D3: non-http(s) redirect target is refused with a typed error ----

    [Fact]
    public async Task RefusesRedirectToNonHttpScheme()
    {
        var handler = new RedirectingHandler(
            firstStatus: HttpStatusCode.Redirect,
            location: new Uri("file:///etc/passwd"));
        var client = new DefaultApiClient(new HttpClient(handler));
        var ex = await Assert.ThrowsAsync<ApiException>(() => client.SendRequestAsync(
            "GET",
            new Uri("http://origin.example.com/start"),
            new Dictionary<string, string>(),
            null
        ));

        // The blocked redirect must surface as an error, not a silent 3xx.
        Assert.Single(handler.Requests);
        Assert.Contains("non-http", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    // ---- T-D1: exceeding maxRedirects throws "too many redirects" ----

    [Fact]
    public async Task ThrowsWhenRedirectChainExceedsMax()
    {
        // Always-redirect handler: every response is a 302 pointing at the
        // same origin, so the loop runs until maxRedirects is exhausted.
        var handler = new AlwaysRedirectHandler(
            new Uri("http://origin.example.com/next"));
        var transport = TransportOptions.Builder().MaxRedirects(3).Build();
        var client = new DefaultApiClient(new HttpClient(handler), transport);
        var ex = await Assert.ThrowsAsync<ApiException>(() => client.SendRequestAsync(
            "GET",
            new Uri("http://origin.example.com/start"),
            new Dictionary<string, string>(),
            null
        ));

        Assert.Contains("redirect", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task AllowsBodylessGetOnHttpsToHttpDowngrade()
    {
        // GET without a body has nothing to replay — the downgrade
        // guard only fires for body-preserving redirects with a body.
        var handler = new RedirectingHandler(
            firstStatus: HttpStatusCode.RedirectKeepVerb,
            location: new Uri("http://downgraded.example.com/landed"));
        var client = new DefaultApiClient(new HttpClient(handler));
        var response = await client.SendRequestAsync(
            "GET",
            new Uri("https://secure.example.com/start"),
            new Dictionary<string, string>(),
            null
        );

        Assert.Equal(2, handler.Requests.Count);
        Assert.Equal(200, response.StatusCode);
    }

    [Fact]
    public async Task AllowsBodyReplayOnHttpsToHttpsRedirect()
    {
        // No downgrade — both legs are HTTPS. Body replay is allowed
        // on 307 because the wire is still encrypted end-to-end.
        var handler = new RedirectingHandler(
            firstStatus: HttpStatusCode.RedirectKeepVerb,
            location: new Uri("https://secure.example.com/landed"));
        var client = new DefaultApiClient(new HttpClient(handler));
        var response = await client.SendRequestAsync(
            "POST",
            new Uri("https://secure.example.com/start"),
            new Dictionary<string, string>(),
            "payload"
        );

        Assert.Equal(2, handler.Requests.Count);
        Assert.Equal(200, response.StatusCode);
    }

    // ---- response-body-read-error-not-wrapped ----

    [Fact]
    public async Task WrapsBodyReadFailureInApiException()
    {
        // A failure that happens AFTER headers (during body read) must surface
        // as the uniform ApiException, not the raw IOException leaked by
        // HttpClient — matching the send-phase error treatment so callers have
        // one error type for the whole transport phase.
        var client = new DefaultApiClient(new HttpClient(new FailingBodyHandler()));
        var ex = await Assert.ThrowsAsync<ApiException>(() => client.SendRequestAsync(
            "GET",
            new Uri("http://example.com/truncated"),
            new Dictionary<string, string>(),
            null
        ));

        // The original transport error is preserved as the cause (either the
        // IOException directly or an HttpRequestException wrapping it,
        // depending on the runtime's HttpContent buffering).
        Assert.NotNull(ex.InnerException);
        bool causeChainHasIo = false;
        for (Exception? cur = ex.InnerException; cur != null; cur = cur.InnerException)
        {
            if (cur is IOException)
            {
                causeChainHasIo = true;
                break;
            }
        }
        Assert.True(causeChainHasIo, "Expected an IOException somewhere in the cause chain");
    }

    // ---- Gap AL: Content-Encoding lie surfaces as ApiException ----

    [Fact]
    public async Task LyingGzipContentEncodingSurfacesApiException()
    {
        // Canonical scenario AL: the server sets Content-Encoding: gzip but the
        // body is plain (non-gzip) bytes. The client MUST surface the SDK's
        // ApiException — no crash, no corrupt passthrough of the undecoded
        // bytes. Before the fix the plaintext was returned verbatim as if it
        // were the decoded body; now the lying encoding is decoded explicitly
        // and the InvalidDataException is wrapped as ApiException.
        byte[] plaintext = Encoding.UTF8.GetBytes("this is not gzip");
        var handler = new EncodedBodyHandler(
            HttpStatusCode.OK,
            plaintext,
            contentEncoding: "gzip",
            contentType: "application/json");
        var client = new DefaultApiClient(new HttpClient(handler));

        var ex = await Assert.ThrowsAsync<ApiException>(() => client.SendRequestAsync(
            "GET",
            new Uri("http://example.com/lying-gzip"),
            new Dictionary<string, string>(),
            null
        ));

        Assert.Contains("decode", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    // ---- close-lifecycle-three-way: use-after-close throws SDK error ----

    [Fact]
    public async Task UseAfterCloseThrowsApiException()
    {
        var client = new DefaultApiClient(
            CreateMockHttpClient(HttpStatusCode.OK, "{}"));
        client.Dispose();

        // A request on a disposed client must surface a typed SDK error, not
        // the raw ObjectDisposedException leaked by HttpClient.
        await Assert.ThrowsAsync<ApiException>(() => client.SendRequestAsync(
            "GET",
            new Uri("http://example.com/echo"),
            new Dictionary<string, string>(),
            null
        ));
    }

    [Fact]
    public void NonexistentCaCertPathThrowsApiExceptionAtConstruction()
    {
        // ca-cert-fail-fast: an explicitly configured CA certificate path that
        // cannot be read or parsed must fail fast at construction with the
        // SDK's ApiException rather than silently falling back to the system
        // trust store (security theater).
        var transport = TransportOptions.Builder().CaCertPath("/nonexistent/ca.pem").Build();
        Assert.Throws<ApiException>(() => new DefaultApiClient(transport));
    }

    // ---- multipart-text-part-contenttype-csharp ----
    // The code fix lives in BuildTextPart (StringContent emitted with no
    // default text/plain Content-Type). A faithful regression test needs a
    // real multipart/form-data operation to exercise BuildMultipartContent —
    // a plain Dictionary body routes through the JSON path, not multipart.
    // Deferred to the petstore-fixture wave (a multipart upload op).

    /// <summary>
    /// First request returns <paramref name="firstStatus"/> with a Location
    /// header pointing at <paramref name="location"/>; subsequent requests
    /// return 200 OK with an empty body. Records every request received
    /// so tests can assert on stripped/preserved headers and the count of
    /// hops actually performed.
    /// </summary>
    private sealed class RedirectingHandler : HttpMessageHandler
    {
        private readonly HttpStatusCode _firstStatus;
        private readonly Uri _location;
        public List<HttpRequestMessage> Requests { get; } = [];

        public RedirectingHandler(HttpStatusCode firstStatus, Uri location)
        {
            _firstStatus = firstStatus;
            _location = location;
        }

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken)
        {
            // Snapshot the request — DefaultApiClient disposes it after
            // the redirect hop, which would otherwise clear Headers.
            var snapshot = new HttpRequestMessage(request.Method, request.RequestUri);
            foreach (var h in request.Headers)
            {
                snapshot.Headers.TryAddWithoutValidation(h.Key, h.Value);
            }
            Requests.Add(snapshot);

            if (Requests.Count == 1)
            {
                var redirect = new HttpResponseMessage(_firstStatus)
                {
                    Content = new StringContent(""),
                };
                redirect.Headers.Location = _location;
                return Task.FromResult(redirect);
            }
            return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StringContent(""),
            });
        }
    }

    /// <summary>
    /// Every response is a 302 redirect to the same fixed location, so the
    /// manual redirect loop never terminates on its own — it runs until the
    /// configured maxRedirects cap is hit. Used to exercise the
    /// redirect-exhaustion guard.
    /// </summary>
    private sealed class AlwaysRedirectHandler : HttpMessageHandler
    {
        private readonly Uri _location;

        public AlwaysRedirectHandler(Uri location)
        {
            _location = location;
        }

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken)
        {
            var redirect = new HttpResponseMessage(HttpStatusCode.Redirect)
            {
                Content = new StringContent(""),
            };
            redirect.Headers.Location = _location;
            return Task.FromResult(redirect);
        }
    }

    /// <summary>
    /// Returns a 200 OK whose body stream throws when read, simulating a
    /// connection reset / truncated transfer AFTER response headers arrived.
    /// </summary>
    private sealed class FailingBodyHandler : HttpMessageHandler
    {
        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken)
        {
            var response = new HttpResponseMessage(HttpStatusCode.OK)
            {
                Content = new StreamContent(new ThrowingStream()),
            };
            return Task.FromResult(response);
        }

        private sealed class ThrowingStream : Stream
        {
            public override bool CanRead => true;
            public override bool CanSeek => false;
            public override bool CanWrite => false;
            public override long Length => throw new NotSupportedException();
            public override long Position
            {
                get => throw new NotSupportedException();
                set => throw new NotSupportedException();
            }

            public override int Read(byte[] buffer, int offset, int count) =>
                throw new IOException("connection reset while reading body");

            public override Task<int> ReadAsync(byte[] buffer, int offset, int count, CancellationToken cancellationToken) =>
                throw new IOException("connection reset while reading body");

            public override ValueTask<int> ReadAsync(Memory<byte> buffer, CancellationToken cancellationToken = default) =>
                throw new IOException("connection reset while reading body");

            public override void Flush() { }
            public override long Seek(long offset, SeekOrigin origin) => throw new NotSupportedException();
            public override void SetLength(long value) => throw new NotSupportedException();
            public override void Write(byte[] buffer, int offset, int count) => throw new NotSupportedException();
        }
    }

    /// <summary>
    /// Returns a response whose raw bytes are emitted verbatim with a
    /// declared <c>Content-Encoding</c> header — without actually compressing
    /// them. Used to simulate a server that lies about its Content-Encoding
    /// (Gap AL). Because the mock handler bypasses the real HttpClientHandler,
    /// AutomaticDecompression never runs and the Content-Encoding header
    /// survives, so the client's own decode guard is exercised.
    /// </summary>
    private sealed class EncodedBodyHandler : HttpMessageHandler
    {
        private readonly HttpStatusCode _statusCode;
        private readonly byte[] _body;
        private readonly string _contentEncoding;
        private readonly string _contentType;

        public EncodedBodyHandler(
            HttpStatusCode statusCode,
            byte[] body,
            string contentEncoding,
            string contentType)
        {
            _statusCode = statusCode;
            _body = body;
            _contentEncoding = contentEncoding;
            _contentType = contentType;
        }

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken)
        {
            var response = new HttpResponseMessage(_statusCode)
            {
                Content = new ByteArrayContent(_body),
            };
            response.Content.Headers.TryAddWithoutValidation("Content-Type", _contentType);
            response.Content.Headers.TryAddWithoutValidation("Content-Encoding", _contentEncoding);
            return Task.FromResult(response);
        }
    }

    private sealed class RawByteHandler : HttpMessageHandler
    {
        private readonly HttpStatusCode _statusCode;
        private readonly byte[] _body;
        private readonly string _contentType;

        public RawByteHandler(HttpStatusCode statusCode, byte[] body, string contentType)
        {
            _statusCode = statusCode;
            _body = body;
            _contentType = contentType;
        }

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken)
        {
            var response = new HttpResponseMessage(_statusCode)
            {
                Content = new ByteArrayContent(_body),
            };
            response.Content.Headers.TryAddWithoutValidation("Content-Type", _contentType);
            return Task.FromResult(response);
        }
    }

    private static HttpClient CreateMockHttpClient(
        HttpStatusCode statusCode,
        string body,
        Dictionary<string, string>? responseHeaders = null
    )
    {
        var handler = new MockHandler(statusCode, body, responseHeaders ?? []);
        return new HttpClient(handler);
    }

    private sealed class CapturingHandler : HttpMessageHandler
    {
        private readonly Func<HttpRequestMessage, Task> _onRequest;
        private readonly HttpStatusCode _statusCode;
        private readonly string _body;

        public CapturingHandler(
            Func<HttpRequestMessage, Task> onRequest,
            HttpStatusCode statusCode = HttpStatusCode.OK,
            string body = "{}"
        )
        {
            _onRequest = onRequest;
            _statusCode = statusCode;
            _body = body;
        }

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken
        )
        {
            await _onRequest(request);
            return new HttpResponseMessage(_statusCode)
            {
                Content = new StringContent(_body),
            };
        }
    }

    private sealed class MockHandler : HttpMessageHandler
    {
        private readonly HttpStatusCode _statusCode;
        private readonly string _body;
        private readonly Dictionary<string, string> _headers;
        private readonly Dictionary<string, IEnumerable<string>> _multiValueHeaders;

        public MockHandler(
            HttpStatusCode statusCode,
            string body,
            Dictionary<string, string>? headers = null,
            Dictionary<string, IEnumerable<string>>? multiValueHeaders = null
        )
        {
            _statusCode = statusCode;
            _body = body;
            _headers = headers ?? [];
            _multiValueHeaders = multiValueHeaders ?? [];
        }

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken
        )
        {
            var response = new HttpResponseMessage(_statusCode)
            {
                Content = new StringContent(_body),
            };

            foreach (var header in _headers)
            {
                response.Headers.TryAddWithoutValidation(header.Key, header.Value);
            }

            foreach (var header in _multiValueHeaders)
            {
                response.Headers.TryAddWithoutValidation(header.Key, header.Value);
            }

            return Task.FromResult(response);
        }
    }
}
